import sys,random,itertools
sys.path.insert(0,'/workspace/project')
from ebpf.create_dfa import create,DENY
from syntax import parse_policy

NAMES=['A','B','C']
LABELS={'A':10,'B':4,'C':7}
reg=[{'name':n,'label':LABELS[n]} for n in NAMES]
cols=sorted(NAMES,key=lambda n:LABELS[n])
NAME2COL={n:i for i,n in enumerate(cols)}

def rand_path(maxlen=3):
    return tuple(random.choice(NAMES) for _ in range(random.randrange(maxlen+1)))

def atom_truth(kind,p,w):
    k=len(p)
    if kind=='match':return w==p
    if kind=='startswith':return w[:k]==p
    if kind=='endswith':return w[-k:]==p if k else True
    if kind=='contains':
        if k==0:return True
        return any(w[i:i+k]==p for i in range(len(w)-k+1))
    raise ValueError

def pred_str(node):
    kind=node[0]
    if kind=='atom':return f"{node[1]}({','.join(node[2])})"
    if kind=='not':return f"not({pred_str(node[1])})"
    return f"({pred_str(node[1])} {kind} {pred_str(node[2])})"

def evalpred(node,w):
    kind=node[0]
    if kind=='atom':return atom_truth(node[1],node[2],w)
    if kind=='not':return not evalpred(node[1],w)
    if kind=='and':return evalpred(node[1],w) and evalpred(node[2],w)
    if kind=='or':return evalpred(node[1],w) or evalpred(node[2],w)

def randpred(depth=1):
    if depth>=3 or random.random()<.55:
        kind=random.choice(['match','startswith','endswith','contains'])
        return ('atom',kind,rand_path())
    kind=random.choice(['and','or','not'])
    if kind=='not':return ('not',randpred(depth+1))
    return (kind,randpred(depth+1),randpred(depth+1))

def run_image(image,w):
    s=0
    for x in w:
        t=image['rows'][s][NAME2COL[x]]
        if t==DENY:return False
        s=t
    return image['accept'][s]

random.seed(2)
for trial in range(3000):
    rules=[]
    text=''
    for _ in range(random.randint(0,4)):
        p=randpred()
        a=random.choice(['allow','drop'])
        rules.append((p,a))
        text+=pred_str(p)+' '+a+';'
    try:p=parse_policy(text)
    except Exception as e:
        print('parse fail',text,e);raise
    image=create(text,reg,p)
    # all words up to len 7 ternary
    for L in range(8):
        for w in itertools.product(NAMES,repeat=L):
            allow=any(a=='allow' and evalpred(pr,w) for pr,a in rules)
            drop=any(a=='drop' and evalpred(pr,w) for pr,a in rules)
            exp=allow and not drop
            got=run_image(image,w)
            if exp!=got:
                print('MISMATCH',text,w,exp,got,image);raise SystemExit
print('policy membership all ok')
